// ── Map each row array to a typed document ───────────────────────────────────
const FIELDS = [
  "record_id","date","month","site_id","site_type","region","climate_zone",
  "equipment_type","project_phase","units_requested","units_available",
  "units_fulfilled","unmet_demand","avg_engine_hours_per_day",
  "avg_idle_hours_per_day","utilization_rate",
];

const NUM_FIELDS = new Set([
  "units_requested","units_available","units_fulfilled","unmet_demand",
  "avg_engine_hours_per_day","avg_idle_hours_per_day","utilization_rate",
]);

function toDoc(row) {
  const doc = {};
  FIELDS.forEach((f, i) => {
    if (f === "date") doc[f] = new Date(row[i]);
    else if (NUM_FIELDS.has(f)) doc[f] = Number(row[i]);
    else doc[f] = row[i];
  });
  return doc;
}

// ── Main ──────────────────────────────────────────────────────────────────────
async function main() {
  await mongoose.connect(MONGO_URI);
  console.log("✅ Connected to MongoDB");

  // Create index to allow upserts
  await DemandHistory.createIndexes();

  const docs = rows.map(toDoc);
  let inserted = 0;
  let updated = 0;

  for (const doc of docs) {
    const result = await DemandHistory.updateOne(
      { record_id: doc.record_id },
      { $set: doc },
      { upsert: true }
    );
    if (result.upsertedCount) inserted++;
    else updated++;
  }

  const total = await DemandHistory.countDocuments();
  console.log(`\n📊 Seed complete:`);
  console.log(`   Inserted: ${inserted}`);
  console.log(`   Updated : ${updated}`);
  console.log(`   Total documents in demand_history: ${total}`);

  await mongoose.disconnect();
  console.log("🔌 Disconnected from MongoDB");
}

main().catch((err) => {
  console.error("❌ Seed failed:", err);
  process.exit(1);
});
